#!/usr/bin/env bash
# Usage: entire_report.sh <PR number>...  — prints Entire gate summary + all findings per PR.
cd /c/Users/Lenovo/.aaCoding/miTch || exit 1
for n in "$@"; do
  br=$(gh pr view "$n" --json headRefName,headRefOid --jq '.headRefName + " " + .headRefOid')
  sha=${br#* }; br=${br% *}
  echo "################ PR #$n  ($br)"
  gh api "repos/Late-bloomer420/miTch/commits/$sha/check-runs" \
    --jq '.check_runs[]|select(.name=="Entire Gates")|"status=\(.status) conclusion=\(.conclusion)\n\(.output.summary)"'
  entire trail finding --branch "$br" --status any --freshness any --include-dismissed --json 2>&1 | python -c "
import json,sys
raw=sys.stdin.read()
try: d=json.loads(raw)
except Exception: print('FINDINGS READ FAILED:', raw[:400]); sys.exit()
print('counts:', d['counts'])
order=['high','medium','low']
for f in sorted(d['findings'], key=lambda x: order.index(x['severity']) if x['severity'] in order else 9):
    l=f.get('location') or {}
    print(f\"\n[{f['severity'].upper()} conf={f['confidence']} status={f['status']}] {l.get('filePath')}:{l.get('startLine')}-{l.get('endLine')}\n{f['body']}\")
if d.get('has_more'): print('!! MORE FINDINGS NOT SHOWN (has_more=true)')
"
  echo
done

